import {
  Check,
  Column,
  CreateDateColumn,
  Entity,
  PrimaryColumn,
  Unique,
  UpdateDateColumn,
} from 'typeorm';
import { type Plan } from '../../common/types/roles';

/** RLS: visible when it is the current organization or the current user is a member. */
@Entity({ name: 'organizations' })
@Unique('uq_organizations_slug', ['slug'])
@Check('ck_organizations_plan', `plan IN ('free', 'pro', 'enterprise')`)
export class Organization {
  /** Generated by the application so the RLS context can be set before the insert. */
  @PrimaryColumn('uuid')
  id!: string;

  @Column({ type: 'text' })
  name!: string;

  @Column({ type: 'text' })
  slug!: string;

  @Column({ type: 'text', default: 'free' })
  plan!: Plan;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt!: Date;

  @UpdateDateColumn({ name: 'updated_at', type: 'timestamptz' })
  updatedAt!: Date;
}
